{
  "id": "vg002",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Báo cáo chỉ ghi nhận việc đổi giờ sinh hoạt và số thành viên tăng diễn ra đồng thời nhưng không xác định mối quan hệ nhân quả giữa hai sự việc này."
}

{
  "id": "vg004",
  "label": "SUPPORTED",
  "evidence_ids": ["e1", "e2"],
  "explanation": "Cả hai bản kiểm kê số 1 và số 2 đều xác nhận nhà sinh hoạt Hạt Nắng có đúng 3 cửa ra vào."
}

 {
  "id": "vg005",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Tài liệu cung cấp thông tin về sân tập Bờ Trăng có mái che, nhưng không có mô tả về sân tập Bờ Nắng."
}

{
  "id": "vg011",
  "label": "SUPPORTED",
  "evidence_ids": [
    "e1",
    "e2"
  ],
  "explanation": "Đoạn e1 cho biết lớp dệt của trung tâm Hừng Đông học tại phòng Lá, và đoạn e2 xác nhận phòng dùng cho lớp dệt này có đúng 24 ghế."
}

 {
  "id": "vg019",
  "label": "REFUTED",
  "evidence_ids": [
    "e1"
  ],
  "explanation": "Biên bản kiểm kê xác nhận tủ sách Mạch Nguồn có 180 cuốn, không phải 200 cuốn."
}

{
  "id": "vg021",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Có hai nguồn tin cậy ngang nhau cung cấp số lượng học viên trái ngược nhau (22 và 25), và chưa có thông báo giải quyết sự khác biệt này."
}

{
  "id": "vg037",
  "label": "REFUTED",
  "evidence_ids": [
  "e1"
  ],
  "explanation": "Bằng chứng e1 xác nhận hội chợ Trăng Non chỉ diễn ra tại sân Đông và không có hoạt động nào tại sân Tây, trái ngược với claim."
}

{
  "id": "vg040",
  "label": "SUPPORTED",
  "evidence_ids": ["e1"],
  "explanation": "Trước khi sửa chữa phòng Sỏi có 50 ghế, sau sửa chữa có 60 ghế. Mức tăng là (60-50)/50 = 10/50 = 20%."
}

{
  "id": "vg045",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Thông tin về mái che được xác nhận, nhưng không có thông tin về hệ thống đèn chiếu sáng của sân Mây."
}

 {
  "id": "vg056",
  "label": "SUPPORTED",
  "evidence_ids": [
    "e1",
    "e2"
  ],
  "explanation": "Xưởng Cỏ Hồng cho phép học viên đã hoàn thành buổi hướng dẫn an toàn tham dự buổi thực hành (e1), và Huy đã hoàn thành buổi hướng dẫn này (e2)."
}

{
  "id": "vg058",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Thông báo cho biết lớp Nắng Sớm không học ở phòng A ngày 01/10/2026, nhưng chưa công bố phòng thay thế cụ thể là phòng C hay không."
}

{
  "id": "vg062",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Biết đầu kỳ có 30 thành viên và có 5 người gia nhập, nhưng chưa thống kê số người rời nhóm, nên không thể xác định số thành viên cuối kỳ nhiều hơn đầu kỳ hay không."
}

{
  "id": "vg064",
  "label": "REFUTED",
  "evidence_ids": [
    "e1"
  ],
  "explanation": "Đội Kênh Xanh xác nhận buổi tổng vệ sinh vẫn diễn ra như lịch cũ, trái ngược với thông tin buổi tổng vệ sinh đã bị hủy."
}

 {
  "id": "vg065",
  "label": "REFUTED",
  "evidence_ids": ["e1", "e2"],
  "explanation": "Vườn Lưng Đồi ban đầu có 40 cây, nhận thêm 5 cây và chuyển đi 8 cây. Tổng số cây sau đợt điều chỉnh là 40 + 5 - 8 = 37 cây, thấp hơn số lượng ban đầu, nên số cây không tăng."
}

{
  "id": "vg068",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Evidence chỉ cung cấp thông tin về lớp làm nến tại chi nhánh phía Bắc và nêu rõ không có thông tin về chi nhánh phía Nam."
}

 {
  "id": "vg074",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Tài liệu chỉ cung cấp thông tin đội trưởng hiện tại là chị Mai và ghi rõ là không có lịch sử nhân sự, nên không đủ cơ sở để xác nhận đội Hoa Biển chưa từng thay đội trưởng."
}

{
  "id": "vg079",
  "label": "SUPPORTED",
  "evidence_ids": [
    "e2"
  ],
  "explanation": "Bản đính chính chính thức xác nhận giờ bắt đầu đúng của buổi đọc thơ Bến Sương là 19:00, thay thế cho thông tin 18:00 trước đó."
}

{
  "id": "vg084",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Bằng chứng chỉ cung cấp số lượng thành viên của hội Gió Đồng vào ngày 01/09/2026, không cung cấp dữ liệu cho năm 2025."
}
